.mn { display: flex; gap: 22px; padding: 22px 24px 60px; max-width: 1420px; margin: 0px auto; --c: #96002a; }.mn-toc { width: 236px; flex: 0 0 auto; position: sticky; top: 18px; align-self: flex-start; background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: 12px; padding: 12px; max-height: calc(-36px + 100vh); overflow: auto; font-size: 13.5px; }.mn-toc h6 { margin: 8px 6px 4px; font-size: 11.5px; color: var(--muted); letter-spacing: 0.08em; font-weight: 700; }.mn-toc a { display: block; padding: 5px 8px; border-radius: 6px; color: var(--ink); text-decoration: none; }.mn-toc a.s { padding-left: 22px; font-size: 13px; color: rgb(71, 85, 105); }.mn-toc a:hover, .mn-toc a.on { background: rgb(241, 245, 249); color: rgb(17, 17, 17); }.mn-main { flex: 1 1 0%; min-width: 0px; }.mn .card { background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: 12px; padding: 22px 26px; margin-bottom: 18px; }.mn h2 { margin: 0px 0px 6px; font-size: 22px; display: flex; align-items: center; gap: 10px; }.mn h2 .tag { font-size: 12px; padding: 2px 9px; border-radius: 999px; color: rgb(255, 255, 255); background: var(--c); font-weight: 700; }.mn .lead { color: rgb(71, 85, 105); margin: 0px 0px 14px; font-size: 15px; line-height: 1.8; }.mn h3 { font-size: 16px; margin: 18px 0px 8px; color: var(--c); }.mn p, .mn li { font-size: 14.5px; line-height: 1.8; }.mn table.t { border-collapse: collapse; width: 100%; font-size: 14px; margin: 6px 0px 10px; }.mn table.t th, .mn table.t td { border: 1px solid var(--line); padding: 7px 10px; vertical-align: top; text-align: left; line-height: 1.7; }.mn table.t th { background: rgb(248, 250, 252); white-space: nowrap; }.mn .k { display: inline-block; background: color-mix(in srgb,var(--c) 10%,#fff); color: var(--c); border: 1px solid color-mix(in srgb,var(--c) 35%,#fff); border-radius: 6px; padding: 0px 6px; font-weight: 700; font-size: 13.5px; white-space: nowrap; }.mn .note { background: rgb(255, 251, 235); border: 1px solid rgb(253, 230, 138); border-radius: 8px; padding: 8px 12px; font-size: 14px; margin: 8px 0px; }.mn .note b { color: rgb(180, 83, 9); }.mn .warn { background: rgb(254, 242, 242); border: 1px solid rgb(254, 202, 202); border-radius: 8px; padding: 8px 12px; font-size: 14px; margin: 8px 0px; }.mn .warn b { color: rgb(185, 28, 28); }.flow { display: flex; align-items: stretch; overflow-x: auto; padding: 14px 2px 10px; }.flow .st { flex: 0 0 auto; width: 176px; background: rgb(255, 255, 255); border: 2px solid var(--line); border-radius: 12px; padding: 14px 12px 10px; position: relative; text-decoration: none; color: var(--ink); transition: 0.15s; }.flow .st:hover { border-color: var(--c); box-shadow: 0 4px 14px color-mix(in srgb,var(--c) 18%,transparent); }.flow .st .n { position: absolute; top: -12px; left: 12px; background: var(--c); color: rgb(255, 255, 255); font-weight: 800; font-size: 12px; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }.flow .st b { display: block; font-size: 14.5px; margin: 2px 0px 4px; }.flow .st .do { font-size: 12.5px; color: rgb(71, 85, 105); line-height: 1.5; }.flow .st .act { margin-top: 7px; font-size: 12px; color: var(--c); font-weight: 700; }.flow .st .who { margin-top: 5px; font-size: 11.5px; color: var(--muted); }.flow .ar { flex: 0 0 auto; width: 30px; display: flex; align-items: center; justify-content: center; color: rgb(148, 163, 184); font-size: 20px; }.lanes { margin-top: 10px; border-top: 1px dashed var(--line); padding-top: 10px; }.lane { display: flex; align-items: center; gap: 10px; margin: 7px 0px; font-size: 13px; flex-wrap: wrap; }.lane .lb { flex: 0 0 auto; width: 122px; font-weight: 700; padding: 5px 10px; border-radius: 8px; background: color-mix(in srgb,var(--c) 10%,#fff); color: var(--c); text-align: center; }.lane .path { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }.lane .path span { background: rgb(241, 245, 249); border-radi